adcs_quat_t qm, qp, qc, q_rel;
adcs_vec3_t v;
double n;

if ((predicted == NULL) || (measured == NULL) || (rotation_vector == NULL) || (angle == NULL))
    return ADCS_E_NULL;

if (adcs_quat_normalize(measured, &qm) != ADCS_OK) {
    *rotation_vector = (adcs_vec3_t){0.0, 0.0, 0.0};
    *angle = INFINITY;
    return ADCS_E_DEGENERATE;
}
if (adcs_quat_normalize(predicted, &qp) != ADCS_OK) {
    *rotation_vector = (adcs_vec3_t){0.0, 0.0, 0.0};
    *angle = INFINITY;
    return ADCS_E_DEGENERATE;
}

qc = adcs_quat_conjugate(&qp);
q_rel = adcs_quat_multiply(&qm, &qc);
if (q_rel.w < 0.0) {
    q_rel.w = -q_rel.w;
    q_rel.x = -q_rel.x;
    q_rel.y = -q_rel.y;
    q_rel.z = -q_rel.z;
}

*angle = 2.0 * acos(ADCS_CLAMP(q_rel.w, 0.0, 1.0));

v = (adcs_vec3_t){q_rel.x, q_rel.y, q_rel.z};
n = adcs_vec3_norm(&v);
if (n <= ADCS_EPS_NORM) {
    *rotation_vector = (adcs_vec3_t){0.0, 0.0, 0.0};
} else {
    *rotation_vector = adcs_vec3_scale(&v, *angle / n);
}

return ADCS_OK;

