candidates.raw:
adcs_quat_t q_pred_n, q_meas_n, q_pred_conj, q_rel;
adcs_vec3_t v;
double vnorm, w_clamped;

if ((predicted == NULL) || (measured == NULL) || (rotation_vector == NULL) || (angle == NULL)) {
    return ADCS_E_NULL;
}

rotation_vector->x = 0.0;
rotation_vector->y = 0.0;
rotation_vector->z = 0.0;
*angle = INFINITY;

if (adcs_quat_normalize(predicted, &q_pred_n) != ADCS_OK) {
    return ADCS_E_DEGENERATE;
}
if (adcs_quat_normalize(measured, &q_meas_n) != ADCS_OK) {
    return ADCS_E_DEGENERATE;
}

q_pred_conj = adcs_quat_conjugate(&q_pred_n);
q_rel = adcs_quat_multiply(&q_meas_n, &q_pred_conj);

if (q_rel.w < 0.0) {
    q_rel.w = -q_rel.w;
    q_rel.x = -q_rel.x;
    q_rel.y = -q_rel.y;
    q_rel.z = -q_rel.z;
}

w_clamped = ADCS_CLAMP(q_rel.w, 0.0, 1.0);
*angle = 2.0 * acos(w_clamped);

v.x = q_rel.x;
v.y = q_rel.y;
v.z = q_rel.z;
vnorm = adcs_vec3_norm(&v);
if (vnorm <= ADCS_EPS_NORM) {
    rotation_vector->x = 0.0;
    rotation_vector->y = 0.0;
    rotation_vector->z = 0.0;
} else {
    rotation_vector->x = (*angle) * q_rel.x / vnorm;
    rotation_vector->y = (*angle) * q_rel.y / vnorm;
    rotation_vector->z = (*angle) * q_rel.z / vnorm;
}

return ADCS_OK;

